public function logoutViaBearerToken(string $token): void {
  $this->tokenManager->deleteCompositionToken($token);
}

public function loginViaOneTimeToken(string $token): CompositeToken {
  $cacheKey = cache_key('one-time token', $token);
  $userId = self::decryptUserIdFromCache($cacheKey);
  Cache::forget($cacheKey);
  return $this->logUserIn($this->userRepository->getOne($userId));
}

public function loginViaTwoFactorChallenge(string $loginToken, string $code): CompositeToken {
  $cacheKey = cache_key('two-factor login token', $loginToken);
  $user = $this->userRepository->getOne(self::decryptUserIdFromCache($cacheKey));
  throw_unless($this->twoFactorAuth->verify($user, $code), InvalidCredentialsException::class);
  Cache::forget($cacheKey);
  return $this->logUserIn($user);
}

public function updateUser(User $user, UserUpdateData $dto): User {
  throw_if($user->is_prospect, new UserProspectUpdateDeniedException());
  $data = ['name'=>$dto->name,'email'=>$dto->email,'password'=>$dto->password ?? $user->password];
  if ($dto->avatar) $data['avatar'] = ...maybeStoreAvatar;
  if ($user->sso_provider) Arr::forget($data, ['password','email']);
  $user->update($data);
  if ($dto->role && $user->role !== $dto->role) $user->syncRoles($dto->role);
  return $user->refresh();
}

public function savePreference(User $user, string $key, mixed $value): void {
