public function toggleFavorite(Favoriteable|Model $favoriteable, User $user): ?Favorite {
  $favorite = $favoriteable->favorites()->where('user_id',$user->id)->delete() === 0
    ? $favoriteable->favorites()->create(['user_id'=>$user->id,'position'=>$this->getNextPosition($user)])
    : null;
  if ($favoriteable instanceof Song) { event(new SongFavoriteToggled($favoriteable, (bool)$favorite, $user)); }
  return $favorite;
}

